package hu.synostream.android;
import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
@RunWith(AndroidJUnit4.class)
public class Android053Test {
 final Android050FlowTest flow=new Android050FlowTest();
 @After public void cleanup()throws Exception{if(flow.app!=null)flow.instrumentation.runOnMainSync(()->{flow.app.cancelScan();flow.app.epoch++;flow.app.torrentDraft.close();});flow.cleanup();}
 @Test public void videoAndFolderRequestFinishWhileTorrentReplyIsHeld()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());nas.holdTorrentResponse=true;NasClient client=flow.app.client;DownloadStation downloads=new DownloadStation(client,flow.app.store,flow.app.identity);ExecutorService pool=Executors.newFixedThreadPool(3);try{Future<?> upload=pool.submit(()->downloads.prepare("","fixture.torrent",new byte[]{1,2,3},"Movies"));assertTrue(nas.torrentRequestRead.await(4,TimeUnit.SECONDS));assertArrayEquals(nas.files.get("/Movies/Demo.Movie.2020.mkv"),pool.submit(()->client.readFile("/Movies/Demo.Movie.2020.mkv",100)).get(3,TimeUnit.SECONDS));assertEquals(2,pool.submit(()->client.list("/Movies").size()).get(3,TimeUnit.SECONDS).intValue());assertFalse(upload.isDone());assertEquals(0,nas.starts);nas.releaseTorrentResponse.countDown();upload.get(4,TimeUnit.SECONDS);}finally{nas.releaseTorrentResponse.countDown();pool.shutdownNow();}}}
 @Test public void androidHttpStackDoesNotReplayLostTorrentResponse()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());nas.dropTorrentResponse=true;DownloadStation downloads=new DownloadStation(flow.app.client,flow.app.store,flow.app.identity);try{downloads.prepare("","fixture.torrent",new byte[]{1,2,3},"Movies");fail();}catch(IOException expected){assertTrue(expected.getMessage().startsWith("Nem érkezett biztos NAS-visszaigazolás"));}assertEquals(1,nas.torrentUploads);assertEquals(1,nas.prepares);assertEquals(0,nas.starts);}}
}
